# -*- coding: utf-8 -*-
B=[
dict(a=1,z=2,star=3,
lit='「耶和華對我說：雖有摩西和撒母耳站在我面前，我的心也不傾向這百姓；把他們從我面前趕出去，讓他們出去。他們若對你說：我們往哪裡出去？你就對他們說：耶和華這樣說：定為死亡的，歸死亡；定為刀劍的，歸刀劍；定為饑荒的，歸饑荒；定為被擄的，歸被擄。」',
key=[('摩西','H4872','mosheh','從水中拉出來'),('撒母耳','H8050','shemuel','神已應允'),('站立','H5975','yaamod','站立、代求'),('我的心','H5315','nafshi','我的魂、我的心意'),('趕出','H7971','shalakh','打發、趕走')],
gram=['**{H5975}**（amad，站立）：「站在我面前」是**代求者的姿勢**，如十八章二十節的「我曾站在你面前為他們代求」。這個動詞表示代求不是一句話，而是一個**站立的位置**。','**{H5315}**（nefesh，魂）：這個字本義是「喉嚨、魂」，常指人整個的生命與心意。「我的心不傾向這百姓」是說神的**整個心意**已經定了。'],
exp=['十五章一節一開始就是**整卷書最重的一句話**：雖有摩西和撒母耳站在我面前，我的心也不傾向這百姓。摩西與撒母耳，是舊約最有名的兩位代求者。摩西在金牛犢事件中為百姓求情，神就後悔（出三十二章）；撒母耳在米斯巴為百姓禱告，神就以雷聲擊潰非利士人（撒上七章）。連這兩位都來求，神也不改變。','請留意：這不是說摩西與撒母耳的禱告沒有力量，而是說**這一代的罪，已經過了一個臨界點**。這是上一章「不要為這百姓祈禱」的延續，也是整卷書的**第四次**同類宣告。','二節是一個很殘酷的問答：他們問「我們往哪裡去」，神的答案是**四個「定為」**：死亡、刀劍、饑荒、被擄。這不是偶然的災難，而是一套**事先排好的次序**。**神的審判不是隨機，而是公義。**']),
dict(a=3,z=4,star=2,
lit='「我要命定四樣來攻擊他們，這是耶和華說的：用刀劍殺戮，用狗撕裂，用天空的飛鳥和地上的走獸吞吃、毀滅。我要使他們在地上萬國中成為驚駭，都因猶大王希西家的兒子瑪拿西在耶路撒冷所行的事。」',
key=[('四樣','H702','arbaa','四'),('狗','H3611','hakelavim','狗'),('飛鳥','H5775','of','飛禽'),('瑪拿西','H4519','menasheh','使人忘記'),('驚駭','H2189','zaawah','驚嚇、恐怖')],
gram=['**{H4519}**（Menasheh，瑪拿西）：瑪拿西是猶大**在位最久（五十五年）也最惡**的王。王下二十一章記載他重建邱壇、立偶像、行巫術，並使耶路撒冷流無辜人的血。王下二十四章三至四節也說，猶大的被擄，正是因為瑪拿西的罪。'],
exp=['三節的**四樣**，是一個漸進的畫面：刀劍殺戮，狗撕裂，飛鳥吞吃，走獸毀滅。這是古代近東最可怕的一種死法：**不得埋葬，成為野獸的食物**。這與十四章十六節「無人葬埋」前後呼應。','四節把這一切的根源，指向一個人：**瑪拿西**。他是猶大在位最久的王，也是最惡的王。這個細節讓我們看見，**罪有時間差**：瑪拿西死了一代，他的罪卻仍然在後面的世代發酵。','請小心讀這一節：這不是說後代為先祖的罪下地獄（結十八章）。它的意思是：一個群體的**文化與制度**一旦被帶偏，要花很長的時間才能轉回來；而約西亞的改革（王下二十二至二十三章）雖然真誠，卻**沒有完全逆轉**這個趨勢。']),
dict(a=5,z=5,star=2,
lit='「耶路撒冷啊，誰要憐憫你？誰要為你悲傷？誰要轉過來問你平安？」',
key=[('憐憫','H2550','yakhmol','憐惜'),('悲傷','H5110','yanud','搖頭哀悼'),('轉過來','H5493','yasur','轉身、拐進來'),('問平安','H7965','leshalom','問安'),('耶路撒冷','H3389','yerushalaim','平安之城')],
gram=['**{H2550}**（khamal，憐憫）：這個字比一般的「憐憫」更**具體**，指「手下留情」。**{H7965}**（shalom，平安）：問安、問「你好不好」，是人與人之間最基本的關懷。'],
exp=['五節是一連**三個問句**：誰憐憫你？誰為你悲傷？誰轉過來問你平安？這三句，是一幅**孤立無援**的圖畫。耶路撒冷，名字的意思是「平安之城」，現在卻**沒有一個人肯拐進來問一句：你好嗎？**','請把這一節和十四章十七節放在一起：神說「誰為你悲傷」，而先知說「願我的眼睛晝夜流淚」。**神的問句，被先知的眼淚回答了。**這就是代求者的位置：當全世界都不問，**有一個人還在流淚**。']),
dict(a=6,z=7,star=3,
lit='「你捨棄了我，這是耶和華說的，你往後退；所以我伸手攻擊你，毀壞你；我後悔後悔得疲倦了。我在境內的各城門口，用簸箕簸了他們；我使他們喪失兒女，毀滅我的百姓；他們卻不從自己的道路上轉回。」',
key=[('捨棄','H5203','natashta','離棄'),('後悔','H5162','hinnakhem','後悔、轉意'),('簸','H2219','vaezrem','簸揚'),('簸箕','H4214','bamizreh','簸箕'),('喪失兒女','H7921','shikkalti','使喪子'),('轉回','H7725','shavu','回轉')],
gram=['**{H5162}**（nakham，後悔）：「我後悔後悔得疲倦了」是整段**最讓人驚訝的一句**：神的後悔，不是出錯，而是**一次一次地收回審判，給人機會**；現在，祂疲倦了。**{H2219}**（zarah，簸）：簸穀是把糠和麥子分開，風一吹，輕的飛走了。','**{H7725}**（shuv，回轉）：這個字是耶利米書的**追蹤字**，從三章一直到最後，神一再說「回轉」。這一節說：「他們卻不從自己的道路上轉回」。'],
exp=['六節是一句很讓人心疼的話：我後悔後悔得疲倦了。這是**神的疲倦**。神不是沒有耐性，而是**祂的耐性已經用了很多年**：從摩西到先知，從約西亞到現在，祂一次一次轉意、一次一次等候。**這個疲倦，是愛的疲倦。**','七節是簸穀的畫面。簸箕是用來把穀物拋向空中，讓風吹走糠，留下麥子。「在境內各城門口」是說：**這場審判無處不在**。城門是最公開的地方，**連最安全的地方，也被簸了。**','最後一句是整個控訴的核心：他們卻不從自己的道路上轉回。**神做了這麼多，人卻不轉。**這是聖經對人心最誠實的一句描寫：**苦難本身，不一定帶人回頭。**']),
dict(a=8,z=9,star=2,
lit='「他們的寡婦，在我面前比海沙更多；我使毀滅者在正午攻擊少年人的母親，使痛苦與驚嚇忽然臨到她。生了七個的，衰弱了，她的氣息消沉；她的太陽還在白晝就落了；她蒙羞受辱；他們剩下的，我要在他們仇敵面前，交給刀劍。這是耶和華說的。」',
key=[('寡婦','H490','almenotav','寡婦'),('海沙','H2344','khol','沙子'),('正午','H6672','batsohoraim','正午、午間'),('生七個','H7651','shivah','七（完全的數字）'),('太陽落了','H8121','shimshah','她的太陽'),('蒙羞','H954','boshah','羞愧')],
gram=['**{H7651}**（sheva，七）：「生過七子」是**最完全的福分**（得七子是路得記四章十五節的祝福，撒上二章五節也說「不生育的生了七個」）。這位母親有七個孩子，是**最被羨慕的婦人**；她的太陽在白晝落了，是**福分的徹底翻轉**。'],
exp=['八、九節是**母親的哀歌**。「寡婦比海沙更多」是一個誇張的修辭：**戰爭奪走的，不只是士兵，更是整個家庭**。正午是最明亮的時間，這個毀滅卻在正午來，沒有黑夜的預兆。','九節最動人的一句是：**她的太陽還在白晝就落了**。這位生了七個孩子的母親，是當時人眼中最有福的人，卻在**一個白天裡失去了所有**。這是整卷書最細緻的一個畫面之一：**神的審判，不是冷冰冰的統計，而是一位母親的眼淚。**','請留意：神說這些話的時候，**祂自己也在痛**（六節的疲倦、八節的細節）。審判不是神的冷酷，而是神**不得不**。']),
dict(a=10,z=10,star=3,
lit='「我母親啊，我有禍了！你生我作遍地爭吵的人、遍地相爭的人。我沒有借貸給人，人也沒有借貸給我，人人卻都咒罵我。」',
key=[('禍','H188','oy','哀哉'),('爭吵','H7379','riv','爭訟'),('相爭','H4066','madon','紛爭'),('咒罵','H7043','mekalelooni','咒罵我')],
gram=['**{H7379}**（riv，爭訟）與 **{H4066}**（madon，紛爭）：這兩個字連用，描寫先知**被生下來，就是為了成為爭議的中心**。這句話與約伯記三章、耶利米書二十章十四節同類，是**先知最低谷時的告白**。'],
exp=['十節是先知**第一次**開口，他說的不是神的話，而是**自己的話**：我母親啊，我有禍了。這句話讓我們看見，**先知也是人**。他看見審判的畫面（五至九節），心就碎了。**傳講審判的人，自己也被審判的話折磨。**','先知說：我沒有借貸給人，人也沒有借貸給我，人人卻咒罵我。這是一句很具體的**訴屈**：我沒有跟人有任何利益衝突，**我只是說了神的話**，卻成了眾人的眼中釘。這是所有**忠心傳講真理的人**的處境。','請把這一節與接下來的十五至十八節放在一起讀：這是**耶利米書「告白」系列**的第三篇（十一章十八節至十二章六節、十五章十節至二十一節、十七章十二至十八節、十八章十八至二十三節、二十章七至十八節）。這個系列，我們會一路讀下去。']),
dict(a=11,z=14,star=2,
lit='「耶和華說：我必要堅固你，使你得好處；災禍和苦難的時候，我必使仇敵來求你。人能折斷鐵嗎？就是從北方來的鐵和銅嗎？我必因你在四境內所犯的一切罪，把你的財寶和寶物當作掠物，白白交出，不收價銀。我必使你的仇敵帶著它們，到你不認識的地去，因為在我怒中起了火，要向你們燒起來。」',
key=[('堅固','H8281','sheritikha','堅固你（原文難解）'),('好處','H2896','letov','為了好處'),('銅','H5178','unekhoshet','銅'),('北方','H6828','mitsafon','從北方'),('掠物','H957','labaz','掠物'),('火','H784','esh','火')],
gram=['**{H8281}**（sharah，堅固）：這個字在希伯來文本中**非常難解**，**不同的古譯本與現代譯本各有不同的讀法**。和合本譯作「我必堅固你」，有的譯本作「我必釋放你」，也有的作「我必使你的餘剩」。**講義採和合本的讀法，並把這個難點誠實告訴讀者。**','**{H6828}**（tsafon，北方）：「北方的鐵」指**巴比倫**，也可能指鐵與銅都是北方運來的一種強力金屬，象徵**不可抵擋的力量**。'],
exp=['十一至十四節是整章**最難讀**的一段，原因有兩個：第一，十一節的「堅固」（sharah）原文本身就難解；第二，十一至十四節在不同的譯本裡，**說話的對象**也不一樣：是神對先知說，還是神對百姓說？我們誠實地把這個難點告訴讀者，**不要裝作沒有問題**。','不論怎麼讀，這一段的大方向很清楚：**第一，神仍然看顧忠心的先知**（十一節）；**第二，北方的力量**（巴比倫）**勢不可擋**（十二節）；**第三，百姓的財寶要被掠走**（十三節）；**第四，神的怒火要燒起來**（十四節）。','請留意這一段的**位置**：在先知的第一次訴屈（十節）之後，神**沒有直接回答**他的苦，而是**先轉向審判的現實**。這是耶利米書最誠實的地方：**神不會因為先知痛苦，就改變祂對百姓的判斷。**可是，在十五至二十一節，神**會**回答先知。']),
dict(a=15,z=15,star=3,
lit='「耶和華啊，你知道；求你記念我，眷顧我，為我向逼迫我的人報仇；不要因你的忍耐把我帶走；要知道我為你的緣故受了羞辱。」',
key=[('記念','H2142','zokhreni','記念我'),('眷顧','H6485','pokdeni','眷顧我'),('報仇','H5358','vehinnakem','報復、伸冤'),('逼迫','H7291','meradfay','追逐我的人'),('忍耐','H750','erekh','長（鼻息）、忍耐'),('羞辱','H2781','kherpah','羞辱')],
gram=['**{H5358}**（naqam，報仇）：這個字在聖經裡常指**伸冤**，而不只是報復。**先知把報仇的權柄交給神**，而不是自己動手。這是很重要的一個區別。','**{H750}**（erekh，長）：「不要因你的忍耐把我帶走」是一句**很冒險的禱告**。出埃及記三十四章六節說神「長久忍耐」；先知求神的忍耐不要變成**對仇敵的縱容，使他自己被帶走**。'],
exp=['十五節是先知的**第二次開口**，也是整卷書**第一個長篇的告白禱告**。他向神說了五件事：**求神記念**、**求神眷顧**、**求神伸冤**、**求神不要用忍耐把他帶走**、**要神知道他為神受的羞辱**。這是一個**很真實、很直白**的禱告。','請留意：他沒有說「我來報仇」，他說：**求你為我報仇**。這是舊約**把報仇的權柄交給神**的一個典型：保羅在羅馬書十二章十九節也這樣教導。先知的憤怒是真的，可是他把憤怒**帶到神面前**，而不是**自己拿起刀來**。','最後一句是整個禱告的中心：**要知道我為你的緣故受了羞辱。**這句話讓我們看見，先知的苦，不是因為他做錯，而是因為**他忠心**。這是所有為主受苦的人，最需要被神聽見的一句話。']),
dict(a=16,z=17,star=3,
lit='「你的話語被找到，我就吃了它；你的話成了我的歡喜、我心中的快樂；因為耶和華萬軍之神啊，我是稱為你名下的人。我沒有坐在歡樂人的聚會中，也沒有喜樂；因你的手，我獨自坐著，因為你使我滿了憤怒。」',
key=[('找到','H4672','nimtseu','被找到'),('吃了','H398','vaokhlem','我就吃了它們'),('歡喜','H8342','lesason','歡喜'),('稱為','H7121','nikra','被稱呼'),('宴樂人','H7832','mesakhaqim','歡笑的人'),('獨自','H910','badad','獨自'),('憤怒','H2195','zaam','憤慨')],
gram=['**{H4672}**（matsa，找到）：「你的話語被找到」帶著**意外發現的驚喜**：先知好像在一個地方「碰到」了神的話。**{H398}**（akhal，吃）：「吃」是**把神的話吞進身體裡**，與以西結書三章一至三節吃書卷的畫面相同。','**{H910}**（badad，獨自）：先知「獨自坐著」，是**被分別出來的孤單**。這個孤單有一個原因：他是「稱為你名下的人」，所以**他不能與歡笑的人同座**。'],
exp=['十六、十七節是**整章最美的一段**，也是整個「告白系列」的光點：**你的話語被找到，我就吃了它，你的話成了我的歡喜、我心中的快樂。**「吃」是一個很具體的動作：不是研究，不是背誦，而是**吞進去，變成自己的生命**。','可是請看緊接著的一句：**我沒有坐在歡樂人的聚會中，也沒有喜樂；因你的手，我獨自坐著。**同一個人，**一邊說神的話是歡喜快樂，一邊說自己孤單憤怒**。這不是矛盾，而是**一個很真實的屬靈經歷**：領受神的話，**帶來內心的歡喜**，也**使人與世界分別**，帶來孤單。','這一段讓我們學到：**為什麼稱為神名下的人，會有孤單？**因為他與神的心意靠近了，就**與世界的笑聲有了距離**。這個孤單，不是被神拋棄，而是**被神拉近**的另一面。']),
dict(a=18,z=18,star=3,
lit='「我的痛苦為何長久？我的傷口為何無法醫治，不肯痊癒呢？你對我真像一條會欺騙人的溪流、不可靠的水嗎？」',
key=[('痛苦','H3511','kevi','我的痛苦'),('長久','H5331','netsakh','持久、永久'),('傷痕','H4347','umakkati','我的創傷'),('無法醫治','H605','anushah','無法醫治'),('欺騙的溪','H391','akhzav','欺騙的（乾涸的溪）'),('不可靠','H539','neemanu','可靠、穩固')],
gram=['**{H391}**（akhzav，欺騙）：這個字原指**一條夏天會乾涸的溪流**（約伯記六章十五至二十節也有同樣的比喻）：冬天水很多，夏天最需要時卻**沒有水**。先知在這裡，把神比作這樣一條溪。**這是整卷書最大膽的一句。**','**{H539}**（aman，可靠）：「不可靠」是 aman 的否定形，這個字與「阿們」同字根。先知問：**難道你是一位不阿們的神嗎？**'],
exp=['十八節是先知的**第三次開口**，也是整卷書最大膽的一句話：**難道你待我真像一條會欺騙人的溪流嗎？**這個比喻，來自巴勒斯坦的地理：有些溪流冬天水勢洶湧，夏天最需要時卻乾涸。先知說：**神啊，祢會不會像這條溪流？**','請小心讀：這**不是**先知對神的定罪，而是**一個痛苦中的人，把最深的懼怕說出來**。與十四章八、九節的百姓一樣，這是**絕望中的誠實**。聖經把這句話收進經卷，是要我們知道：**對神說真話，是被接納的。**','這節經文是整卷書「先知的告白」的**核心經文**之一：先知可以這樣對神說話，**神的回答不是責備，而是邀請回來**（十九節）。**神沒有因為他說了這句話就收回他的呼召**。']),
dict(a=19,z=19,star=3,
lit='「所以耶和華這樣說：你若回轉，我就使你回來，使你站在我面前；你若把寶貴的和下賤的分別出來，你就要像我的口。他們要歸向你，你卻不可歸向他們。」',
key=[('回轉','H7725','tashuv','回轉、回來'),('站在面前','H5975','taamod','站立、事奉'),('寶貴','H3368','yaqar','寶貴的'),('下賤','H2151','mizzolel','下賤的、輕賤的'),('分別','H3318','totsi','帶出來、分別'),('口','H6310','kefi','像我的口')],
gram=['**{H7725}**（shuv，回轉）：這個字在十九節出現**四次**：你若回轉（shuv），我就使你回來（shuv）；他們要歸向你（shuv），你卻不可歸向他們（shuv）。**同一個字，在一句話裡反覆出現**，是整段的**鑰字**。','**{H6310}**（peh，口）：「像我的口」是**先知的呼召的更新**。一章九節神說：「我將我的話放在你口中」；現在，**神說：你要重新成為我的口**。'],
exp=['十九節是**神對先知的回答**，也是整章的**轉折點**。神**沒有**直接安慰他、**沒有**說「你不用難過」，而是說：**你若回轉**。這是一個很讓人意外的回答：**神對先知說：你也需要回轉。**','這不是說先知犯了大罪，而是**他在苦難中，語言開始偏離**。他說「你像會欺騙人的溪流」，神就對他說：**把寶貴的和下賤的分別出來**。意思是：**你說的話裡，有真實的感受，也有被痛苦扭曲的話；你要學會把它們分開。**','請留意最後一句：**他們要歸向你，你卻不可歸向他們。**這是先知的**處境**：他是站在**百姓與神之間**的人，**方向是百姓朝向他，他不朝向百姓**。**牧者不是配合會眾，而是帶領會眾歸向神。**']),
dict(a=20,z=21,star=3,
lit='「我要使你向這百姓成為堅固的銅牆；他們要攻擊你，卻不能勝過你，因為我與你同在，要拯救你，搭救你，這是耶和華說的。我要搭救你脫離惡人的手，救贖你脫離強暴人的手。」',
key=[('銅牆','H2346','lekhomat nekhoshet','銅牆'),('攻擊','H3898','venilkhamu','攻打'),('勝過','H3201','yukhelu','能夠、勝過'),('拯救','H3467','lehoshiekha','拯救你'),('救贖','H6299','vefidtikha','贖回你'),('強暴人','H6184','aritsim','強暴的人')],
gram=['**{H6299}**（padah，救贖）：這個字用於**付代價贖回**（出十三章十三節，頭生的要贖）。神說：我要**贖**你，是用**祂自己**付上代價。','**{H3467}**（yasha，拯救）：這個字與「耶穌」（Yeshua）同字根。「我與你同在，要拯救你」，是一句**把應許與同在連在一起**的話。'],
exp=['二十、二十一節是整章**最安慰的結尾**。神重申一章十八至十九節的應許：**我要使你向這百姓成為堅固的銅牆；他們要攻擊你，卻不能勝過你，因為我與你同在。**請對照一章：**這是第二次**，神把同樣的應許給了先知。**神沒有因為先知的訴屈，就收回祂的承諾。**','請留意這個**順序**：十節先知哭訴，十五至十八節先知禱告，十九節神說「你若回轉」，二十、二十一節神說「我與你同在」。**神的回答是兩段：先呼召回轉，再應許同在。**這是整卷書的一個**縮影**：神的審判與應許，**同時並存**。','「我要拯救你，搭救你，救贖你」，三個動詞在**兩節**裡反覆出現。**這個重複，是神安撫先知的方式。**神不只是說一次，而是**一遍又一遍**地說：我要救你，我要救你，我要救你。**這是一位知道你疲憊的神。**']),
]
